export function dependenciesValid(nodes: string[], edges: Array<[string, string]>): boolean {
  if (nodes.length === 0) return true;

  const nodeSet = new Set<string>();
  const nodeMap = new Map<string, string>(); // node -> parent

  // 1. Check for duplicate nodes
  for (const node of nodes) {
    if (nodeSet.has(node)) {
      return false;
    }
    nodeSet.add(node);
    nodeMap.set(node, null);
  }

  // 2. Validate edges: every edge endpoint must be declared
  for (const [from, to] of edges) {
    if (!nodeSet.has(from)) {
      return false;
    }
    if (!nodeSet.has(to)) {
      return false;
    }
    nodeMap.set(from, to);
  }

  // 3. Check for cycles using DFS
  const visited = new Set<string>();
  const recStack = new Set<string>();

  function hasCycle(node: string): boolean {
    visited.add(node);
    recStack.add(node);

    const parent = nodeMap.get(node);
    if (parent) {
      if (parent === null) {
        // Self-loop
        return true;
      }
      if (visited.has(parent)) {
        return true;
      }
      if (recStack.has(parent)) {
        return true;
      }
      if (hasCycle(parent)) {
        return true;
      }
    }

    recStack.delete(node);
    return false;
  }

  for (const node of nodes) {
    if (hasCycle(node)) {
      return false;
    }
  }

  return true;
}

